for c in $C; do
 g=$(curl -s -m 10 "https://boards-api.greenhouse.io/v1/boards/$c/jobs" | jq -r '.jobs|length' 2>/dev/null); [ "${g:-0}" -gt 0 ] 2>/dev/null && echo "greenhouse $c $g"
 l=$(curl -s -m 10 "https://api.lever.co/v0/postings/$c?mode=json" | jq -r 'if type=="array" then length else 0 end' 2>/dev/null); [ "${l:-0}" -gt 0 ] 2>/dev/null && echo "lever $c $l"
 a=$(curl -s -m 10 "https://api.ashbyhq.com/posting-api/job-board/$c" | jq -r '.jobs|length' 2>/dev/null); [ "${a:-0}" -gt 0 ] 2>/dev/null && echo "ashby $c $a"
 w=$(curl -s -m 10 "https://apply.workable.com/api/v1/widget/accounts/$c" | jq -r '.jobs|length' 2>/dev/null); [ "${w:-0}" -gt 0 ] 2>/dev/null && echo "workable $c $w"
 s=$(curl -s -m 10 "https://api.smartrecruiters.com/v1/companies/$c/postings?limit=1" | jq -r '.totalFound' 2>/dev/null); [ "${s:-0}" -gt 0 ] 2>/dev/null && echo "smartrecruiters $c $s"
done
